public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    // Try all possible substrings of the first string
    String first = strings.get(0);
    int n = first.length();

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String substring = first.substring(i, j);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();

            boolean isValid = true;
            for (String s : strings) {
                if (!s.contains(substring) && !s.contains(reversedSubstring)) {
                    isValid = false;
                    break;
                }
            }

            if (isValid) {
                maxLength = Math.max(maxLength, j - i);
            }
        }
    }

    return maxLength;
}

