public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1;
    }
    // The formula to calculate the maximum number of regions formed by N triangles
    // is derived from the pattern that each new triangle can intersect all previous
    // triangles creating new regions.
    return 1 + 3 * N * (N + 1) / 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula for the maximum number of regions created by N triangles
    // in a plane is given by R(N) = N^2 + N + 2
    return N * N + N + 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative.");
    }
    // The formula to calculate the maximum number of regions
    // formed by N triangles is 2 * (N^2 + N + 1)
    return 2 * (N * N + N + 1);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    // The formula to calculate the maximum number of regions is 2^(N+1)
    return (int) Math.pow(2, N + 1);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, one region (the whole plane)
    }
    // For each triangle, it can intersect with all previous triangles in a way that
    // maximizes the number of regions. The formula derived from this is:
    // Regions = N * (N + 1) / 2 + 1
    return (N * (N + 1) / 2) + 1;
}

