public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (paths == null || paths.length == 0) {
        return "cannot be travelled";
    }

    // Create an adjacency list to represent the graph
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int i = 0; i < n; i++) {
        graph.put(i, new ArrayList<>());
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        if (path.length != 2) {
            continue; // Invalid path entry, skip it
        }
        int from = path[0];
        int to = path[1];
        graph.get(from).add(to);
        graph.get(to).add(from); // Assuming undirected graph
    }

    // Use BFS to determine if there is a path from start to end
    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visited = new HashSet<>();
    queue.add(start[0]);
    visited.add(start[0]);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int neighbor : graph.get(current)) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

