public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonCount, totalLength);
    commonCount /= gcd;
    totalLength /= gcd;

    String fraction = commonCount + "/" + totalLength;
    if (commonCount == totalLength) {
        fraction = String.valueOf(commonCount);
    }

    return "appx(" + word1 + ", " + word2 + ") = " + fraction;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words must not be null");
    }

    int len1 = word1.length();
    int len2 = word2.length();
    int commonCount = 0;

    boolean[] used = new boolean[len2];

    for (int i = 0; i < len1; i++) {
        for (int j = 0; j < len2; j++) {
            if (!used[j] && word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    int totalLength = len1 + len2;
    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/0";
    }

    int gcd = gcd(commonCount, totalLength);

    String result = "appx(" + word1 + ", " + word2 + ") = ";
    if (gcd == 0) {
        result += "0";
    } else {
        result += commonCount / gcd + "/" + totalLength / gcd;
    }

    return result;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words must not be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    boolean[] usedInWord1 = new boolean[word1.length()];
    boolean[] usedInWord2 = new boolean[word2.length()];
    int commonCount = 0;

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (!usedInWord1[i] && !usedInWord2[j] && word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                usedInWord1[i] = true;
                usedInWord2[j] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words must not be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int commonLetters = 0;
    for (int i = 0; i < 26; i++) {
        commonLetters += Math.min(count1[i], count2[i]);
    }

    int sumLengths = word1.length() + word2.length();
    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    int gcd = gcd(commonLetters, sumLengths);
    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + (sumLengths / gcd);
}

public static String appx(String word1, String word2) {
    // Convert words to uppercase to ensure case insensitivity
    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    // Create sets of characters for each word
    Set<Character> set1 = new HashSet<>();
    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    // Find common characters
    set1.retainAll(set2);
    int commonCount = set1.size();

    // Calculate the sum of the lengths of the two words
    int lengthSum = word1.length() + word2.length();

    // Calculate the greatest common divisor (GCD) of commonCount and lengthSum
    int gcd = gcd(commonCount, lengthSum);

    // Reduce the fraction by dividing both numerator and denominator by GCD
    int reducedNumerator = commonCount / gcd;
    int reducedDenominator = lengthSum / gcd;

    // Return the result as a string
    return "appx(" + word1 + ", " + word2 + ") = " + reducedNumerator + (reducedDenominator != 1 ? "/" + reducedDenominator : "");
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }

        String[] months = {"January", "February", "March", "April", "May", "June", 
