        int weekdayIndex = calendar.get(java.util.Calendar.DAY_OF_WEEK);

        String monthName = months[month - 1];
        String weekdayName = weekdays[weekdayIndex - 1];

        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException e) {
