    int remaining = s.length();

    while (remaining > 0) {
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
                remaining--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

