public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[j - 1][i - 1][k]) {
                    dp[j][i][k] = true;
                    if (k + num <= sum) {
                        dp[j][i][k + num] = true;
                    }
                }
            }
        }
    }

    for (int lenA = 1; lenA <= n / 2; lenA++) {
        if (sum * lenA % n == 0) {
            int sumA = sum * lenA / n;
            if (dp[lenA][n][sumA]) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
