public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) return false; // Early exit if s is too short

    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        seen.add(s.substring(i, i + k));
    }
    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    int allPossible = 1 << k; // 2^k

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == allPossible) {
            return true;
        }
    }

    return seen.size() == allPossible;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || s.length() < k) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        int index = 0;
        for (int j = i; j < i + k; j++) {
            index = (index << 1) + (s.charAt(j) - '0');
        }
        found[index] = true;
    }

    for (boolean isFound : found) {
        if (!isFound) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] seen = new boolean[totalSubstrings];

    int allOnes = totalSubstrings - 1; // Binary number with k 1s
    int hashValue = 0;

    for (int i = 0; i < s.length(); i++) {
        // Add the new bit to the hash value
        hashValue = (hashValue << 1) & allOnes | (s.charAt(i) - '0');

        // We start counting valid substrings after we have at least k characters
        if (i >= k - 1 && !seen[hashValue]) {
            seen[hashValue] = true;
            totalSubstrings--;

            // If all binary substrings of length k are found, return true
            if (totalSubstrings == 0) {
                return true;
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) return false;

    int totalPossibleCombinations = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleCombinations];
    int allOnes = totalPossibleCombinations - 1;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        value = ((value << 1) & allOnes) | (s.charAt(i) - '0');
        if (i >= k - 1 && !found[value]) {
            found[value] = true;
            totalPossibleCombinations--;
            if (totalPossibleCombinations == 0) {
                return true;
            }
        }
    }

    return false;
}

