public int minInsertions(String s) {
    int leftNeeded = 0; // Number of '(' needed to balance ')'
    int rightNeeded = 0; // Number of ')' needed to balance '('
    int balance = 0; // Current balance of '(' and ')'

    for (char ch : s.toCharArray()) {
        if (ch == '(') {
            // If there is a need for ')' to balance ')', can only be balanced by '('
            if (balance < 0) {
                rightNeeded += Math.abs(balance);
                balance = 0;
            }
            balance++;
        } else if (ch == ')') {
            balance--;
            // If balance is -1, it means there was an extra ')'
            if (balance == -1) {
                rightNeeded++;
                balance = 0; // Reset balance as we added a '(' virtually
            }
        }
    }

    // If balance > 0, there are extra '(' that need ')' to balance
    if (balance > 0) {
        leftNeeded = balance;
    }

    return leftNeeded + rightNeeded;
}

public int minInsertions(String s) {
    int leftNeeded = 0; // Number of '(' needed to balance ')'
    int rightNeeded = 0; // Number of ')' needed to balance '('
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            // If we encounter '(', we need a ')' to balance it
            rightNeeded++;
            i++;
        } else {
            // If we encounter ')', we need a '(' to balance it
            rightNeeded--;
            i++;
            // Check if there are consecutive ')' which need two '(' to balance
            if (i < s.length() && s.charAt(i) == ')') {
                i++;
            } else {
                // If there is only one ')', it needs one '(' to balance
                leftNeeded++;
            }
        }

        // If rightNeeded goes negative, it means we have more '(' than needed
        if (rightNeeded == -1) {
            rightNeeded = 0;
            leftNeeded++;
        }
    }

    // The total number of insertions needed is the sum of leftNeeded and rightNeeded
    return leftNeeded + rightNeeded;
}

public int minInsertions(String s) {
    int open = 0; // Count of open parentheses '(' needed
    int insertions = 0; // Count of insertions made

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open += 2; // Each '(' needs two ')'
            // If we have an odd number of ')' needed, we need to insert one ')'
            if (open % 2 == 1) {
                insertions++;
                open--;
            }
        } else if (c == ')') {
            open--; // One ')' is matched or needed
            if (open == -1) {
                insertions++; // Need to insert a '(' to balance
                open = 1; // Treat as if we added '(' and still need one ')'
            }
        }
    }

    return insertions + open; // Remaining open needs to be closed
}

public int minInsertions(String s) {
    int open = 0, close = 0, insertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close > 0) {
                insertions += open > 0 ? 1 : 2;
                open = Math.max(0, open - 1);
                close = 0;
            }
            open++;
        } else {
            close++;
            if (close == 2) {
                if (open > 0) {
                    open--;
                } else {
                    insertions++;
                }
                close = 0;
            }
        }
    }
    if (close == 1) {
        insertions += open > 0 ? 1 : 2;
    }
    insertions += open * 2;
    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // Keeps track of open parentheses '('
    int insertions = 0; // Counts the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open++;
        } else { // s.charAt(i) == ')'
            if (open > 0) {
                open--; // Match with an open parenthesis
            } else {
                insertions++; // Insert a '(' to match this ')'
            }
            // Check if the next character is also ')', if so, we match this ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it's matched
            } else {
                insertions++; // Insert a ')' to match this '('
            }
        }
    }

    // Add insertions for any unmatched open parentheses
    insertions += open;

    return insertions;
}

