public int findMinFibonacciNumbers(int k) {
    if (k < 1) return 0;

    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    while (k > 0) {
        while (a > k) {
            int temp = a - b;
            b = a;
            a = temp;
        }
        k -= a;
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k < 1) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    // Subtract the largest Fibonacci number less than or equal to k
    // and recursively solve the remaining value
    return 1 + findMinFibonacciNumbers(k - a);
}

