public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    char[] chars = new char[n];
    int i = n - 1;

    while (k > 0) {
        int remaining = k - (i + 1);
        if (remaining >= 26) {
            chars[i] = 'z';
            k -= 26;
        } else {
            chars[i] = (char) ('a' + remaining);
            k -= (remaining + 1);
        }
        i--;
    }

    for (int j = 0; j <= i; j++) {
        chars[j] = 'a';
    }

    return new String(chars);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(k, 25);
        result.setCharAt(i, (char) ('a' + add));
        k -= add;
    }
    return result.toString();
}

