public static int countDigitOne(int n) {
    if (n <= 0) return 0;

    int count = 0;
    long factor = 1;

    while (n / factor != 0) {
        long lowerNum = n - (n / factor) * factor;
        long curDigit = (n / factor) % 10;
        long higherNum = n / (factor * 10);

        if (curDigit == 0) {
            count += higherNum * factor;
        } else if (curDigit == 1) {
            count += higherNum * factor + lowerNum + 1;
        } else {
            count += (higherNum + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

