public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxCount = 0;

    // Arrays to store the count of continuous 1s
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;

                maxCount = Math.max(maxCount, horizontal[i][j]);
                maxCount = Math.max(maxCount, vertical[i][j]);
                maxCount = Math.max(maxCount, diagonal[i][j]);
                maxCount = Math.max(maxCount, antiDiagonal[i][j]);
            }
        }
    }

    return maxCount;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Directions: right, down, down-right, down-left
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal (right)
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                // Vertical (down)
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                // Diagonal (down-right)
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                // Anti-diagonal (down-left)
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1;

                // Update the maximum length found
                for (int k = 0; k < 4; k++) {
                    maxLength = Math.max(maxLength, dp[i][j][k]);
                }
            }
        }
    }

    return maxLength;
}

