    int n = mat[0].length;

    // Directions for horizontal, vertical, diagonal, and anti-diagonal
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int[] dir : directions) {
        int currentMax = 0;
        int[][] dp = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    int prevI = i - dir[0];
                    int prevJ = j - dir[1];
                    if (prevI >= 0 && prevI < m && prevJ >= 0 && prevJ < n && mat[prevI][prevJ] == 1) {
                        dp[i][j] = dp[prevI][prevJ] + 1;
                    } else {
                        dp[i][j] = 1;
                    }
                    currentMax = Math.max(currentMax, dp[i][j]);
                }
            }
        }
        maxLine = Math.max(maxLine, currentMax);
    }

    return maxLine;
}

