public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first digit that is smaller than the digit next to it
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i-th digit)
    reverse(digits, i + 1, digits.length - 1);

    // Convert the char array back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case the result is out of the integer range
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
    int x = digits[i];
    int smallestIndex = i + 1;
    for (int j = i + 2; j < len; j++) {
        if (digits[j] > x && digits[j] < digits[smallestIndex]) {
            smallestIndex = j;
        }
    }

    // Step 3: Swap the found smallest digit with digits[i]
    char temp = digits[i];
    digits[i] = digits[smallestIndex];
    digits[smallestIndex] = temp;

    // Step 4: Sort the digits after (i+1) in ascending order
    java.util.Arrays.sort(digits, i + 1, len);

    // Step 5: Convert the char array to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow or invalid number
    }
}

