public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Initialize an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0; // Base case: 0 can be represented by 0 perfect squares

    // Precompute all perfect squares less than or equal to n
    int[] squares = new int[(int) Math.sqrt(n) + 1];
    for (int i = 1; i * i <= n; i++) {
        squares[i] = i * i;
    }

    // Fill the dp array with the minimum number of perfect squares
    for (int i = 1; i <= n; i++) {
        for (int j = 1; squares[j] <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - squares[j]] + 1);
        }
    }

    return dp[n];
}

